package net.civeira.phylax.features.oauth.tokensecurity.application;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.exception.NotAllowedException;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenRevocationGateway;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenSigner;

/**
 * Verifies JWT tokens for all OAuth/OIDC grant flows.
 *
 * Delegates signature verification to {@link TokenSigner} and revocation checks to
 * {@link TokenRevocationGateway}. Returns parsed claims or an empty Optional on any failure.
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class TokenVerifier {

  private static final String CLAIM_USER_NAME = "sub";
  private static final String CLAIM_CLIENT_ID = "azp";
  private static final String CLAIM_AUDIENCE_ID = "aud";
  private static final String CLAIM_SCOPE = "scope";
  private static final String CHALLENGE = "challenge";
  private static final String REFRESH_SCOPE = "refresh";
  private static final String MFA_SCOPE = "mfa";

  private final TokenSigner tokenSigner;
  private final TokenRevocationGateway revocationGateway;
  private final ObjectMapper mapper;

  public Optional<String> verifyMfa(String token, String tenant) {
    return verifyScoped(token, MFA_SCOPE, tenant);
  }

  public Optional<String> verifyRefresh(String token, String tenant) {
    return verifyScoped(token, REFRESH_SCOPE, tenant);
  }

  public Optional<String> verifyToken(String token, String scope, String tenant) {
    return verifyScoped(token, scope, tenant);
  }

  public Optional<RefreshTokenInfo> verifyRefreshInfo(String token, String tenant) {
    try {
      Map<String, Object> payload = tokenSigner.verifyTokenPayload(tenant, token);
      if (payload.isEmpty()) {
        return Optional.empty();
      }
      List<String> scopes = claimAsList(payload.get(CLAIM_SCOPE));
      if (scopes.size() != 1 || !scopes.contains(REFRESH_SCOPE)) {
        return Optional.empty();
      }
      String jti = claimAsString(payload.get("jti"));
      Instant expiresAt = resolveExpiry(payload);
      if (jti != null && !jti.isBlank() && revocationGateway.isRevoked(jti, tenant)) {
        return Optional.empty();
      }
      List<String> aud = claimAsList(payload.get(CLAIM_AUDIENCE_ID));
      return Optional
          .of(RefreshTokenInfo.builder().username(claimAsString(payload.get(CLAIM_USER_NAME)))
              .client(claimAsString(payload.get(CLAIM_CLIENT_ID)))
              .audiences(null == aud ? List.of() : aud).jti(jti).expiresAt(expiresAt).build());
    } catch (NotAllowedException nae) {
      return Optional.empty();
    }
  }

  public Optional<String> tokenJti(String token, String tenant) {
    try {
      Map<String, Object> payload = tokenSigner.verifyTokenPayload(tenant, token);
      if (payload.isEmpty()) {
        return Optional.empty();
      }
      String jti = claimAsString(payload.get("jti"));
      return jti == null || jti.isBlank() ? Optional.empty() : Optional.of(jti);
    } catch (NotAllowedException nae) {
      return Optional.empty();
    }
  }

  public <T> Optional<T> verifyChallenger(Class<T> type, String token, String tenant) {
    try {
      Map<String, Object> payload = tokenSigner.verifyTokenPayload(tenant, token);
      if (payload.isEmpty()) {
        return Optional.empty();
      }
      List<String> scopes = claimAsList(payload.get(CLAIM_SCOPE));
      if (scopes.size() == 1 && scopes.contains(CHALLENGE)) {
        @SuppressWarnings("unchecked")
        Map<String, Object> asMap = (Map<String, Object>) payload.get(CHALLENGE);
        return Optional.of(mapper.convertValue(asMap, type));
      }
      return Optional.empty();
    } catch (NotAllowedException nae) {
      log.warn("Wrong challenger", nae);
      return Optional.empty();
    }
  }

  private Optional<String> verifyScoped(String token, String scope, String tenant) {
    try {
      Map<String, Object> payload = tokenSigner.verifyTokenPayload(tenant, token);
      if (payload.isEmpty()) {
        return Optional.empty();
      }
      List<String> scopes = claimAsList(payload.get(CLAIM_SCOPE));
      String jti = claimAsString(payload.get("jti"));
      if (jti != null && !jti.isBlank() && revocationGateway.isRevoked(jti, tenant)) {
        return Optional.empty();
      }
      if (scopes.size() == 1 && scopes.contains(scope)) {
        return Optional.ofNullable(claimAsString(payload.get(CLAIM_USER_NAME)));
      }
      return Optional.empty();
    } catch (NotAllowedException nae) {
      log.warn("Wrong {} token", scope);
      return Optional.empty();
    }
  }

  private Instant resolveExpiry(Map<String, Object> payload) {
    Object exp = payload.get("exp");
    if (exp instanceof Number n) {
      return Instant.ofEpochSecond(n.longValue());
    }
    return Instant.now().plus(90, ChronoUnit.DAYS);
  }

  private String claimAsString(Object value) {
    return null == value ? null : mapper.convertValue(value, String.class);
  }

  @SuppressWarnings("unchecked")
  private List<String> claimAsList(Object value) {
    if (null == value) {
      return List.of();
    }
    if (value instanceof List) {
      return (List<String>) value;
    }
    if (value instanceof String[]) {
      return Arrays.asList((String[]) value);
    }
    return List.of(mapper.convertValue(value, String.class));
  }
}
